alter table public.schoolpro_cbt_answers add column if not exists feedback text,add column if not exists marked_by uuid references auth.users(id),add column if not exists marked_at timestamptz;
create or replace function public.mark_schoolpro_theory_answer(p_answer uuid,p_marks numeric,p_feedback text default null) returns void language plpgsql security definer set search_path='' as $$declare a public.schoolpro_cbt_answers;at public.schoolpro_cbt_attempts;t public.schoolpro_cbt_tests;q public.schoolpro_question_bank;begin select * into a from public.schoolpro_cbt_answers where id=p_answer for update;if a.id is null then raise exception 'Answer not found';end if;select * into at from public.schoolpro_cbt_attempts where id=a.attempt_id;select * into t from public.schoolpro_cbt_tests where id=at.test_id;select * into q from public.schoolpro_question_bank where id=a.question_id;if q.question_type<>'theory' then raise exception 'Only theory answers require manual marking';end if;if not(public.schoolpro_member_can_manage(t.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=t.school_id and m.user_id=auth.uid() and m.role::text in('teacher','class_teacher','exam_officer','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;if p_marks<0 or p_marks>q.marks then raise exception 'Marks must be between 0 and question maximum';end if;update public.schoolpro_cbt_answers set marks_awarded=p_marks,feedback=p_feedback,marked_by=auth.uid(),marked_at=now(),is_correct=null where id=a.id;update public.schoolpro_cbt_attempts set score=(select coalesce(sum(coalesce(x.marks_awarded,0)),0) from public.schoolpro_cbt_answers x where x.attempt_id=at.id) where id=at.id;end$$;
revoke all on function public.mark_schoolpro_theory_answer(uuid,numeric,text) from public,anon;grant execute on function public.mark_schoolpro_theory_answer(uuid,numeric,text) to authenticated;
alter table public.schoolpro_subscriptions enable row level security;drop policy if exists schoolpro_subscription_school_read on public.schoolpro_subscriptions;create policy schoolpro_subscription_school_read on public.schoolpro_subscriptions for select to authenticated using(public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='super_admin' and p.status='active'));drop policy if exists schoolpro_subscription_ihlink_write on public.schoolpro_subscriptions;create policy schoolpro_subscription_ihlink_write on public.schoolpro_subscriptions for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='super_admin' and p.status='active')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='super_admin' and p.status='active'));